head.script:
scwin.draw = function() {
    var options = {
        "caption": "Half Yearly Revenue Analysis",
        "ayaxisname": "Revenue", //웹접근성 y축 값, 두번째 y축값은 dataObj json 객체에 속성으로 넣어줌 sayaxisname속성명 삽입 
        "axaxisname": "Year", //웹접근성 x축 값 
        "pYAxisName": "Sales",
        "sYAxisName": "Profit %",
        "numberPrefix": "$",
        "sNumberSuffix": "%"
    };
    chart_test_flash.setChartAttribute(options);
    chart_test_flash.setJSONData(dataObj);
}
scwin.__isEl = function() {
    var el = WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_test_flash').childNodes;
    return el1 = el[1].childNodes;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 4. 4번샘플 실행 후 동일하게 요소검사를 통해 "accessibility_chart_test_flash"를 검색한다.
    //4. After executing sample 4, search for "accessibility_chart_test_flash" through the same element check.
    //Verify 4. <li>Year : 8/6/2006, Revenue : 1327</li>
    WebSquare.wUnit.addCommand("assert", "scwin.__isEl()[1].childNodes[0].innerText == 'Year : 8/6/2006, Revenue : 1327'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isEl()[1].childNodes[0].tagName == 'LI'", "true");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
